B.avZ=new A.d7("\u0627\u0644\u0642\u0644\u0642\u0644\u0629","\u062d\u0631\u0648\u0641 (\u0642\u0637\u0628 \u062c\u062f) \u0625\u0630\u0627 \u0633\u0643\u0646\u062a \u062a\u064f\u0646\u0637\u0642 \u0628\u0635\u0648\u062a \u0627\u0631\u062a\u062f\u0627\u062f\u064a \u062e\u0641\u064a\u0641.","\u0627\u062c\u0639\u0644 \u0627\u0644\u062d\u0631\u0641 \u0627\u0644\u0633\u0627\u0643\u0646 \u064a\u0631\u062a\u062f \u0628\u0635\u0648\u062a \u062e\u0641\u064a\u0641 \u062f\u0648\u0646 \u0623\u0646 \u062a\u0636\u064a\u0641 \u0625\u0644\u064a\u0647 \u062d\u0631\u0643\u0629.")
B.aw5=new A.d7("Qalqalah (echo)","The letters qaaf, taa, baa, jeem and daal with sukoon are pronounced with a light bounce.","Let the letter bounce slightly without adding a vowel.")
B.adB=new A.Y(B.bQ,[B.avZ,B.aw5],t.nb)
B.avM=new A.d7("\u0627\u0644\u0645\u062f \u0627\u0644\u0637\u0628\u064a\u0639\u064a","\u062d\u0631\u0648\u0641 \u0627\u0644\u0645\u062f (\u0627 \u0648 \u064a) \u062a\u064f\u0645\u062f \u0628\u0645\u0642\u062f\u0627\u0631 \u062d\u0631\u0643\u062a\u064a\u0646.","\u0645\u062f\u0651 \u0627\u0644\u0635\u0648\u062a \u062d\u0631\u0643\u062a\u064a\u0646 \u0641\u0642\u0637\u060c \u0644\u0627 \u0623\u0642\u0644 \u0648\u0644\u0627 \u0623\u0643\u062b\u0631.")
