B.adE=new A.Y(B.bQ,[B.avM,B.avL],t.nb)
B.avJ=new A.d7("\u0627\u0644\u0645\u062f \u0627\u0644\u062c\u0627\u0626\u0632","\u0645\u062f\u064c\u0651 \u064a\u062c\u0648\u0632 \u0641\u064a\u0647 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0645\u0642\u062f\u0627\u0631 \u062d\u0633\u0628 \u0646\u0648\u0639\u0647\u060c \u0645\u062b\u0644 \u0627\u0644\u0645\u0646\u0641\u0635\u0644 \u0648\u0627\u0644\u0639\u0627\u0631\u0636 \u0644\u0644\u0633\u0643\u0648\u0646.","\u0627\u0644\u062a\u0632\u0645 \u0645\u0642\u062f\u0627\u0631\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0641\u064a \u062a\u0644\u0627\u0648\u062a\u0643 \u0643\u0644\u0647\u0627\u060c \u0643\u0645\u0627 \u062a\u0633\u0645\u0639\u0647 \u0645\u0646 \u0627\u0644\u0642\u0627\u0631\u0626.")
B.avY=new A.d7("Permissible madd","A madd that may be lengthened by more than one amount depending on its type, such as munfasil or aarid.","Keep one length throughout your recitation, as you hear from the reciter.")
